"""Render the reviewed text-only AMI question pilot from its public evidence bundle."""
import hashlib
from html import escape as e
import json
from pathlib import Path
from site_navigation import project_tabs, experiment_subtabs

ROOT=Path(__file__).resolve().parents[1]
DATA=ROOT/'research/ami-questions'

def para(text):return '<p>'+e(str(text))+'</p>'

def table(number,title,headers,rows):
    return '<div class="ami-table"><table><caption>Table '+str(number)+'. '+e(title)+'</caption><thead><tr>'+''.join('<th scope="col">'+e(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+e(str(x))+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'

def card(q):
    review=q['review'];status=review['decision'];origin=q.get('model','assistant_authored');variant=q.get('prompt_variant','authored')
    evidence=''.join('<li><strong>'+e(c['speaker'])+'</strong> · '+f"{c['start']:.2f}–{c['end']:.2f} s"+' · <code>'+e(c['id'])+'</code>'+para(c['text'])+'</li>' for c in q['evidence'])
    reads=''
    assessment=q.get('reader_content_review')
    if assessment:
        latest=max((int(r['job_id']) for r in q['readbacks'].values()),default=int(assessment['reader_job']))
        if status=='accept' and latest!=int(assessment['reader_job']):
            raise ValueError('Update actual reader content review before publishing newer readbacks: '+q['id'])
        reads+='<div class="callout amber"><strong>Assistant content review · reader job '+e(assessment['reader_job'])+'</strong>'+para('Full prefix: '+assessment['full_prefix_content'])+para('Recent context: '+assessment['recent_content'])+'</div>'
    # Show the first readback per condition and retain exact duplicate runs in JSON.
    seen=set()
    read_order={'full_prefix':0,'recent_60s':1,'question_only':2,'evidence_removed':3}
    for key,r in sorted(q['readbacks'].items(),key=lambda item:(-int(item[1]['job_id']),read_order[item[1]['condition']])):
        if r['condition'] in seen:continue
        seen.add(r['condition']);response=r.get('response') or {}
        text=r.get('answer_text_for_review') or response.get('answer') or r.get('final_text') or 'No parsed answer.'
        reads+='<div class="ami-reader"><strong>'+e(r['condition'].replace('_',' '))+'</strong>'+para(text)+para('Reader self-report: '+str(response.get('fully_answerable','unparsed'))+'. This flag is not a correctness score.')+(para('Output flags: '+', '.join(r['validation_errors'])) if r.get('validation_errors') else '')+(para('A complete answer string is shown from an incomplete JSON object; the raw output remains a formatting failure.') if r.get('answer_extraction')=='complete_json_string_field_from_incomplete_object' else '')+'</div>'
    return '<article class="card ami-question" id="'+e(q['id'])+'" data-origin="'+e(origin)+'" data-status="'+e(status)+'" data-variant="'+e(variant)+'"><div class="ami-labels"><span class="tag">'+e(status)+'</span><span class="tag blue">'+e(origin+(' + reference edit' if q.get('source_candidate_id') else '')+' / '+variant)+'</span></div><h3>'+e(q['question'])+'</h3>'+para('EN2003a · generation/reader source time '+f"{q['at']:.2f} s"+' · requester '+q['requester']+' → separate meeting assistant')+para(q['requester_perspective']+' (inferred from prior speech).')+(para(q['replay_timing_note']) if q.get('replay_timing_note') else '')+'<p class="ami-answer"><strong>Proposed reference:</strong> '+e(q['answer'])+'</p>'+para('Review: '+review.get('note',''))+('<p>Source draft: <a href="#'+e(q['source_candidate_id'])+'">'+e(q['source_candidate_id'])+'</a>. Question text is unchanged.</p>' if q.get('source_candidate_id') else '')+('<p><strong>History review:</strong> '+e(review['history_note'])+'</p>' if review.get('history_note') else '')+('<p><strong>Validation flags:</strong> '+e(', '.join(q['validation_errors']))+'</p>' if q['validation_errors'] else '')+'<details><summary>Supporting transcript and claim annotations</summary><ul class="ami-evidence">'+evidence+'</ul><pre>'+e(json.dumps(q['claims'],ensure_ascii=False,indent=2))+'</pre></details><details><summary>Withheld-answer reader controls</summary>'+reads+'</details><p class="meta"><code>'+e(q['id'])+'</code></p></article>'

def main():
    audit=json.loads((DATA/'audit.json').read_text());records=json.loads((DATA/'all_candidates.json').read_text());lit=json.loads((DATA/'literature.json').read_text())
    accepted=[r for r in records if r['review']['decision']=='accept']
    groups=[]
    for name,r in audit['groups'].items():
        groups.append([name,f"{r['candidates']} / {r['expected_candidates']}",r['truncated_calls'],r['schema_valid'],r['decisions'].get('accept',0),r['decisions'].get('revise',0),r['decisions'].get('reject',0)])
    nav=project_tabs('experiments','../');sub=experiment_subtabs('ami')
    body='<header class="site-nav"><div class="nav-inner"><a class="brand" href="../index.html">AI2AI Duplex</a>'+nav+'</div></header><main id="main"><div class="container">'+sub
    body+='<header class="hero"><p class="eyebrow">AMI text pilot · 16 October 2026</p><h1>Questions that need the meeting so far.</h1><p class="lede">Synthetic requests ask a separate assistant to recover commitments, compare revised plans and connect earlier constraints to a participant’s current task.</p>'+para(str(audit.get('raw_candidates',audit['candidates']))+' raw drafts plus '+str(audit.get('reference_edited',0))+' curated reference edit; '+str(audit['accepted'])+' retained variants after assistant content review. Status: '+audit['status'].replace('_',' ')+'. One development meeting; no audio-model or generalization result.')+'<div class="button-row"><a class="button primary" href="#questions">Inspect the questions</a><a class="button" href="ami-question-audio.html">Listen to the voice-matched follow-up</a><a class="button" href="../research/ami-questions/requests.jsonl">Model-input requests</a><a class="button" href="../research/ami-questions/references.jsonl">Separate reference labels</a></div></header>'
    body+='<nav class="jump-links" aria-label="AMI report sections"><a href="#design">Design</a><a href="#comparison">Prompt comparison</a><a href="#questions">Question review</a><a href="#method">Related pipelines</a><a href="#audio">Later audio replay</a><a href="#resources">Resources and files</a></nav>'
    body+='<section class="section" id="design"><h2>What a valid question must require</h2><p>The same real AMI recording supplies all four source prefixes. The current requesters are B and C; A remains part of their source conversation. A synthetic requester is one of A, B or C, addressing a separate meeting assistant. The source pauses for one independent question/answer branch. EN2003a is a workshop-planning meeting with no formal job-role labels in its metadata; the displayed participant perspectives are inferred from cited earlier speech.</p><p>A valid reference must be supported by completed available speech before the question. A useful history test must need an older fact that the last minute alone cannot supply. Old citations, fluent answers and a reader saying “answerable” do not establish that requirement. Review also checks natural wording, attribution, tentative versus settled plans and answers accidentally revealed by the question.</p><figure class="ami-flow"><div><a href="#method">Read only the source prefix</a><span>→</span><a href="#comparison">Generate question and draft reference</a><span>→</span><a href="#questions">Read without the draft answer</a><span>→</span><a href="#questions">Review evidence and history need</a></div><figcaption>Figure 1. Each question is an independent branch from an original source-time prefix. Proposed references are withheld from the reader and replay inputs.</figcaption></figure><p>Available transcript chunks use manual word timing plus an assumed half-second sentence-release delay. Unfinished sentences can therefore contain audible words not yet in the text prefix. This conservative preparation convention is not streaming ASR. Source start/end times remain visible so overlapping speech is not mistaken for sequential turns.</p></section>'
    body+='<section class="section" id="timing"><h2>Where the requests fit</h2>'+table(1,'Source-clock cutoffs and participant perspectives. W3 replay is reanchored after a complete sentence; text probes retain their original cutoff.',['Prefix','Requester / task perspective','Generation and reader time','Planned paused replay time'],[['W1','C · helping adapt the Psychology call','05:51.00','05:51.00'],['W2','B · programme capacity and poster planning','17:55.00','17:55.00'],['W3','B · volunteered Informatics/Philosophy outreach','24:49.99','26:18.92'],['W4','C · volunteered conference webpage','35:35.50','35:35.50']])+'</section>'
    body+='<section class="section" id="comparison"><h2>Prompt iteration and observed failures</h2><p>Both local models receive identical full prefixes for v1–v3. Direct v1 asks for role-motivated recall. Evidence v2 additionally requests essential older facts, concise evidence and no answer leakage. Review v3 was written after inspecting the first 4B output: it explicitly handles replaced suggestions, limits citation lists and answer length, and avoids questions listing candidate answers. One seed and four development prefixes support diagnosis, not a general ranking.</p>'+table(2,'Raw candidate yield and assistant decisions. Missing requested candidates include truncated or unparseable calls; schema validity does not imply factual correctness.',['Model / prompt','Candidates / requested','Truncated calls','Schema-valid','Accept','Revise','Reject'],groups)+'<p>The first 4B run sometimes revives an earlier suggestion about warning Philosophy applicants that logic may be hard to understand. Later speech simplifies the invitation to a language-relevance clause. Other failures are long citation lists, questions that supply their answer choices and output truncation. All original candidates remain below, including rejections.</p>'
    body+=para('Output allowances are 2,048 Instruct / 6,144 Thinking tokens in the initial run and, following the user’s update, 4,096 / 16,384 in v3. V3 uses a 49,152-token context, an 8 GiB KV cache and vLLM graph execution. Prompt instructions, token allowance and runtime change together; this comparison cannot isolate the effect of prompting alone.')
    body+=para('Packets v4 tests 4B Instruct with short evidence excerpts selected and checked by the assistant from the same available prefixes; it is a supervised selection setting, not an unassisted whole-prefix comparison. No authored question is supplied. The final reader rechecks all candidates against the full/recent/empty/evidence-removed source contexts with references hidden, a 1,024-token allowance and at most eight citations.')
    if (DATA/'findings.json').exists():
        findings=json.loads((DATA/'findings.json').read_text())
        body+=''.join(para(x) for x in findings['observations'])
    body+='</section><section class="section" id="questions"><h2>Inspect questions, references and evidence</h2><p>The filter starts with accepted examples. Change it to inspect every rejected or revisable candidate. References are synthetic annotations reviewed by the assistant, not original AMI ground-truth responses or independently verified human labels. The reader is Qwen3-4B-Instruct-2507; reading 4B-generated questions uses the same model. The reference, evidence selection and inferred requester perspective are withheld from all reader prompts.</p><div class="ami-filters"><label>Decision <select id="status-filter"><option value="accept">Accepted</option><option value="all">All decisions</option><option value="revise">Needs revision</option><option value="reject">Rejected</option></select></label><label>Origin <select id="origin-filter"><option value="all">All origins</option><option value="assistant_authored">Assistant-authored</option><option value="instruct">Local 4B Instruct</option><option value="thinking">Local 30B Thinking</option></select></label><label>Prompt <select id="variant-filter"><option value="all">All prompts</option><option value="authored">Assistant-authored</option><option value="direct_v1">Direct v1</option><option value="evidence_v2">Evidence v2</option><option value="review_v3">Review v3</option><option value="packets_v4">Supervised packets v4</option></select></label><output id="question-count" aria-live="polite"></output></div><div class="ami-questions">'+''.join(card(q) for q in sorted(records,key=lambda q:(q['review']['decision']!='accept',q['at'],q['id'])))+'</div></section>'
    body+='<section class="section" id="method"><h2>What existing pipelines contribute</h2><p>PREME provides the closest inspected meeting-question generation pipeline: split discussion into topics, sample questions and evaluate answerability and coverage. Roundtrip consistency contributes answer reconstruction with the proposed answer withheld. Meta’s Synthetic Data Kit supplies a practical chunk/generate/curate implementation. The timed cutoff and requester motivation are additional design choices here; scripted synthetic QA itself is established practice.</p>'+table(3,'Verified primary sources and the component used in this pilot.',['Work','Method or resource','Relevance and limit'],[[p['title']+' ('+str(p['year'])+')',p['method'],p['relevance']] for p in lit['papers']])+'<ol>'+''.join('<li><a href="'+e(p['url'])+'">'+e(p['title'])+'</a> — '+e(p['authors'])+', '+str(p['year'])+'.</li>' for p in lit['papers'])+'</ol><p><a href="https://github.com/meta-llama/synthetic-data-kit">Meta Synthetic Data Kit</a> · <a href="https://raw.githubusercontent.com/meta-llama/synthetic-data-kit/main/synthetic_data_kit/generators/qa_generator.py">Inspected QA generator source</a> · <a href="../research/ami-questions/LITERATURE.md">Full focused review</a>.</p></section>'
    body+='<section class="section" id="audio"><h2>Convert approved text into an audio replay</h2><p>Question text and grounded reference facts come first. A later replay can assign a consistent synthetic voice to each requester and a separate assistant voice, pause the source recording at its original timestamp, insert the question and let the tested model answer. Generic TTS voices do not sound like the original AMI speakers, so the first condition needs explicit requester identity. Voice-only identity recovery is a separate experiment.</p><p>Question WAVs are model inputs. Optional reference-answer WAVs are listening examples, never model inputs or unique acoustic scoring targets. Independent transcription should check words, numbers and names. Source time stays fixed during the inserted exchange while playback time advances. Each request starts from its own source prefix; synthetic answers do not silently become later context. No TTS has been generated and no live speech-model behavior is claimed by this text pilot.</p></section>'
    resources=audit['resources'];acct=audit.get('accounting') or {}
    rows=[]
    for job in acct.get('jobs',[]):rows.append([job['job_id'],job.get('state',''),job.get('gpu_type','H100 SXM 80 GB'),job.get('elapsed_seconds',''),job.get('gpu_hours',''),job.get('node','')])
    body+='<section class="section" id="resources"><h2>Resources, provenance and downloads</h2><p>Each of jobs 1110768 and 1110785 requests one H100 SXM 80 GB. GPU 0 hosts the 4B generator, 30B generator and 4B reader sequentially in separate processes; no S1, ASR or TTS runs alongside them. The refinement depends on successful completion of the first job. Job 1111068 follows the refinement and uses one H100 SXM 80 GB for 4B Instruct packet generation and reading in a single resident vLLM engine; it loads no 30B model. Maximum one experiment GPU is active. Preparation, review and publication use zero GPUs. Existing checkpoints and the existing inference environment are reused.</p>'
    if rows:body+=table(4,'Actual Slurm allocation accounting; GPU hours use allocated GPU count and allocation duration.',['Job','State','GPU type / VRAM','Elapsed seconds','GPU hours','Node'],rows)
    body+='<p>AMI source: <a href="https://groups.inf.ed.ac.uk/ami/">AMI corpus</a>, <a href="https://groups.inf.ed.ac.uk/ami/corpus/nonscenariomeetings.shtml">EN2003a non-scenario meeting</a>, CC BY 4.0. This pilot adds synthetic questions and reference annotations. No original participant is claimed to have asked these questions. Private model reasoning and cluster paths are excluded from this public bundle.</p><ul>'+''.join('<li><a href="../research/ami-questions/'+name+'">'+label+'</a></li>' for name,label in [('accepted.json','Accepted examples with evidence and diagnostics'),('all_candidates.json','All raw candidates with review decisions'),('requests.jsonl','Requests only: no answer or evidence labels'),('references.jsonl','Separate reference answers and atomic claims'),('audit.json','Audit and allocation summary'),('generation_calls.json','Generation lengths, finish reasons and times'),('prompts.json','Exact generation and reader instructions'),('PROTOCOL.md','Protocol, timing convention and audio plan'),('literature.json','Machine-readable literature review')])+'</ul></section></div></main>'
    body+='<footer class="container site-footer"><p><a href="../research/ami-questions/rubrics.json">Semantic answer rubrics</a> · <a href="../research/ami-questions/model_provenance.json">Pinned model sources</a> · <a href="../research/ami-questions/generation_windows.json">Exact generation prefixes</a> · <a href="../research/ami-questions/replay_windows.json">Planned replay prefixes</a> · <a href="../research/ami-questions/source-ami_question_pilot.py">Initial inference script</a> · <a href="../research/ami-questions/source-ami_question_refinement.py">Refinement inference script</a> · <a href="../research/ami-questions/manifest.json">Public file hashes</a></p></footer>'
    style='''.ami-questions{display:grid;gap:20px}.ami-question h3{font-size:1.1rem}.ami-question p{color:var(--text)}.ami-labels{display:flex;flex-wrap:wrap;gap:8px}.ami-evidence{padding-left:20px}.ami-evidence li{margin:14px 0}.ami-evidence p{margin:4px 0}.ami-answer{border-left:3px solid var(--accent);padding-left:15px}.ami-reader{margin:12px 0;padding:14px;background:var(--surface-2);border-radius:8px}.ami-reader p{margin:6px 0}.ami-table{overflow:auto;margin:20px 0;border:1px solid var(--border);border-radius:10px}.ami-table table{min-width:780px;table-layout:auto}.ami-filters{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin:20px 0}.ami-filters label{display:flex;gap:8px;align-items:center}.ami-filters select{max-width:100%;padding:8px;background:var(--surface);color:var(--text);border:1px solid var(--border);border-radius:6px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}details{margin:14px 0}summary{cursor:pointer;color:var(--accent);font-weight:650}.ami-flow{margin:24px 0;padding:20px;background:var(--surface);border:1px solid var(--border);border-radius:12px}.ami-flow div{display:flex;flex-wrap:wrap;gap:12px;align-items:center}.ami-flow a{padding:8px;border:1px solid var(--border);border-radius:8px;max-width:100%}.ami-question[hidden]{display:none}@media(max-width:480px){.ami-filters label{width:100%;justify-content:space-between}.ami-question{padding:16px}}'''
    script='''const cards=[...document.querySelectorAll('.ami-question')];const fields=['status','origin','variant'];function filter(){let count=0;for(const c of cards){c.hidden=!fields.every(f=>{let v=document.getElementById(f+'-filter').value;return v==='all'||c.dataset[f]===v});if(!c.hidden)count++}document.getElementById('question-count').textContent=count+' questions shown'}for(const f of fields)document.getElementById(f+'-filter').addEventListener('change',filter);filter();function revealAnchor(){let c=document.getElementById(location.hash.slice(1));if(c?.classList.contains('ami-question')){for(const f of fields)document.getElementById(f+'-filter').value='all';filter();c.scrollIntoView()}}window.addEventListener('hashchange',revealAnchor);if(location.hash)revealAnchor();'''
    css=hashlib.sha256((ROOT/'assets/site.css').read_bytes()).hexdigest()[:12]
    page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Reviewed synthetic AMI meeting questions, grounded reference answers, local prompt comparisons and explicit history controls."><meta name="color-scheme" content="light dark"><title>AMI history questions · AI2AI Duplex</title><link rel="stylesheet" href="../assets/site.css?v='+css+'"><style>'+style+'</style></head><body><a class="skip-link" href="#main">Skip to question study</a>'+body+'<script>'+script+'</script></body></html>'
    (ROOT/'experiments/ami-questions.html').write_text(page)
    collection=ROOT/'experiments/index.html';text=collection.read_text()
    if 'id="ami-question-card"' not in text:
        new='<article class="card" id="ami-question-card"><span class="tag">AMI text pilot</span><h3>Questions that need earlier conversation</h3><p>Local text models and assistant-authored requests, exact supporting speech, proposed references and history controls.</p><p><a class="button" href="ami-questions.html">Review the questions</a></p></article>'
        text=text.replace('<div class="card-grid">','<div class="card-grid">'+new,1)
        collection.write_text(text)
    print('Rendered',len(records),'AMI candidates;',len(accepted),'accepted')

if __name__=='__main__':main()
